import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';
import type { ProviderStatus } from '../core/types';
import { ApiKeyEntry } from './ApiKeyEntry';
import { SetupTokenEntry } from './SetupTokenEntry';
import { ModelSelector } from './ModelSelector';
import { TierPicker } from './TierPicker';
import { OllamaSetup } from './OllamaSetup';
import { TogetherSetup } from './TogetherSetup';
import { IconBrain, IconZap, IconSparkle, IconGlobe, IconHome } from '../shared/icons';

const PROVIDER_ICONS: Record<string, React.ComponentType<{ size?: number; className?: string; strokeWidth?: number }>> = {
  anthropic: IconBrain,
  openai: IconZap,
  deepseek: IconZap,
  kimi: IconSparkle,
  google: IconSparkle,
  together: IconGlobe,
  ollama: IconHome,
};

type AuthTab = 'setup-token' | 'api-key' | 'ollama-setup' | 'together-setup';

const mono = (size: number, color = 'rgba(237,240,244,0.38)') => ({
  fontFamily: "'JetBrains Mono', ui-monospace, monospace",
  fontSize: size, letterSpacing: '0.16em',
  textTransform: 'uppercase' as const, color,
});

export function ProviderSetup() {
  const { t } = useTranslation();

  const [status, setStatus] = useState<ProviderStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [authTab, setAuthTab] = useState<Record<string, AuthTab>>({});

  function reload() {
    api<ProviderStatus>('/api/providers')
      .then(setStatus)
      .catch(console.error)
      .finally(() => setLoading(false));
  }

  useEffect(() => { reload(); }, []);

  if (loading) return (
    <div style={{ display: 'flex', justifyContent: 'center', padding: '32px 0' }}>
      <div className="w-6 h-6 border-2 border-ch-accent border-t-transparent rounded-full animate-spin" />
    </div>
  );

  const providers = [
    {
      id: 'anthropic',
      name: 'Anthropic (Claude)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'openai',
      name: 'OpenAI (GPT)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'deepseek',
      name: 'DeepSeek',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'kimi',
      name: 'Kimi',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'google',
      name: 'Google (Gemini)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'together',
      name: 'Together AI',
      tabs: [{ id: 'together-setup' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'together-setup' as AuthTab,
    },
    ...(!status?.is_railway
      ? [{
          id: 'ollama',
          name: 'Ollama (Local)',
          tabs: [{ id: 'ollama-setup' as AuthTab, label: t('providers.localSetup') }],
          defaultTab: 'ollama-setup' as AuthTab,
        }]
      : []),
  ];

  function getTab(providerId: string): AuthTab {
    return authTab[providerId] || providers.find(p => p.id === providerId)!.defaultTab;
  }

  function renderConnectUI(p: typeof providers[0]) {
    const tab = getTab(p.id);
    return (
      <div>
        {p.tabs.length > 1 && (
          <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
            {p.tabs.map(t => (
              <button key={t.id} onClick={() => setAuthTab(prev => ({ ...prev, [p.id]: t.id }))}
                style={{
                  padding: '4px 12px', borderRadius: 4, fontSize: 11, fontWeight: 500,
                  background: tab === t.id ? 'rgba(200,209,217,0.12)' : 'transparent',
                  color: tab === t.id ? '#EDF0F4' : 'rgba(237,240,244,0.62)',
                  border: `1px solid ${tab === t.id ? 'rgba(200,209,217,0.3)' : 'rgba(230,235,242,0.14)'}`,
                  cursor: 'pointer',
                }}
              >{t.label}</button>
            ))}
          </div>
        )}
        {tab === 'setup-token' && <SetupTokenEntry onConnected={reload} />}
        {tab === 'api-key' && <ApiKeyEntry provider={p.id} onConnected={reload} />}
        {tab === 'together-setup' && <TogetherSetup onConnected={reload} />}
        {tab === 'ollama-setup' && <OllamaSetup onConnected={reload} />}
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      {providers.map(p => {
        const profile = status?.profiles?.[p.id];
        const isConnected = profile?.configured ?? false;
        const isActive = status?.active_provider === p.id;
        const currentModel = isActive ? (status?.active_model ?? '') : '';

        return (
          <div key={p.id} style={{
            background: 'rgba(20,24,30,0.78)',
            borderRadius: 6, padding: 20,
            border: `1px solid ${isActive ? 'rgba(200,209,217,0.3)' : 'rgba(230,235,242,0.07)'}`,
          }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{
                  width: 32, height: 32, borderRadius: 4,
                  background: 'rgba(245,239,227,0.06)',
                  border: '1px solid rgba(230,235,242,0.07)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  color: 'rgba(237,240,244,0.62)',
                }}>
                  {(() => { const Icon = PROVIDER_ICONS[p.id] || IconGlobe; return <Icon size={16} strokeWidth={1.75} />; })()}
                </div>
                <div>
                <p style={{
                  fontFamily: "'Fraunces', Georgia, serif",
                  fontSize: 16, letterSpacing: '-0.01em', color: '#EDF0F4', margin: 0,
                }}>{p.name}</p>
                {isActive && (
                  <span style={{ ...mono(9, '#D4A85A'), marginTop: 2, display: 'inline-block' }}>
                    {t('providers.active')}
                  </span>
                )}
                </div>
              </div>

              {isConnected && (
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  {profile?.expired && (
                    <span style={{ fontSize: 11, color: '#D4A85A', border: '1px solid rgba(212,168,90,0.3)', borderRadius: 4, padding: '2px 6px' }}>
                      {t('providers.expired')}
                    </span>
                  )}
                  <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#8EA589' }} />
                  <span style={{ ...mono(10, '#8EA589') }}>
                    {t('providers.connected')}
                  </span>
                </div>
              )}
            </div>

            {!isConnected ? renderConnectUI(p) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                <ModelSelector provider={p.id} currentModel={currentModel} onChanged={reload} />
                {p.id !== 'ollama' && <TierPicker provider={p.id} onChanged={reload} />}
                {!isActive && (
                  <button onClick={async () => {
                    await api('/api/providers/active', { method: 'PUT', body: JSON.stringify({ provider: p.id, model: currentModel || '' }) });
                    reload();
                  }} style={{
                    width: '100%', padding: '8px 16px', fontSize: 13, borderRadius: 4,
                    border: '1px solid rgba(200,209,217,0.3)', color: 'var(--color-ch-accent, #C8D1D9)',
                    background: 'transparent', cursor: 'pointer',
                  }}>
                    {t('providers.setAsActive')}
                  </button>
                )}
                <button onClick={async () => {
                  await api(`/api/providers/${p.id}/disconnect`, { method: 'POST' });
                  reload();
                }} style={{
                  width: '100%', padding: '8px 16px', fontSize: 13, borderRadius: 4,
                  border: '1px solid rgba(217,119,87,0.3)', color: '#D97757',
                  background: 'transparent', cursor: 'pointer',
                }}>
                  {t('providers.disconnect')}
                </button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';

interface Props {
  provider: string;
  currentModel: string;
  onChanged: () => void;
}

export function ModelSelector({ provider, currentModel, onChanged }: Props) {
  const { t } = useTranslation();

  const [models, setModels] = useState<string[]>([]);
  const [selected, setSelected] = useState(currentModel);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    api<{ models: string[] }>(`/api/providers/${provider}/models`)
      .then(data => setModels(data.models))
      .catch(console.error);
  }, [provider]);

  async function save(model: string) {
    setSaving(true);
    try {
      await api('/api/providers/active', {
        method: 'PUT',
        body: JSON.stringify({ provider, model }),
      });
      setSelected(model);
      onChanged();
    } catch (err) {
      console.error('Failed to set model:', err);
    } finally {
      setSaving(false);
    }
  }

  if (!models.length) return null;

  return (
    <div>
      <label style={{
        display: 'block',
        fontFamily: "'JetBrains Mono', ui-monospace, monospace",
        fontSize: 9, letterSpacing: '0.16em', textTransform: 'uppercase',
        color: 'rgba(237,240,244,0.38)', marginBottom: 6,
      }}>
        {t('providers.model')}
      </label>
      <select
        value={selected}
        onChange={e => save(e.target.value)}
        disabled={saving}
        style={{
          width: '100%', boxSizing: 'border-box',
          background: 'rgba(34,40,48,0.55)', border: '1px solid rgba(230,235,242,0.14)',
          color: '#EDF0F4', borderRadius: 4, padding: '8px 12px', fontSize: 13,
          outline: 'none', opacity: saving ? 0.5 : 1,
        }}
      >
        {models.map(m => (
          <option key={m} value={m}>{m}</option>
        ))}
      </select>
    </div>
  );
}

// Chatty — shared TypeScript types

export interface Agent {
  id: string;
  slug: string;
  agent_name: string;
  avatar_url: string;
  personality: string;
  project_root: string;
  onboarding_complete: boolean;
  provider_override: string;
  model_override: string;
  gmail_enabled: boolean;
  gmail_send_enabled?: boolean;
  calendar_enabled: boolean;
  calendar_write_enabled?: boolean;
  drive_enabled?: boolean;
  drive_write_enabled?: boolean;
  google_accounts?: { gmail?: string[]; calendar?: string[]; drive?: string[] };
  whatsapp_session_id?: string;
  telegram_enabled: boolean;
  telegram_bot_token?: string;
  telegram_bot_username?: string;
  telegram_group_enabled: boolean;
  alert_count?: number;
  created_at: string;
  updated_at: string;
}

export interface AgentAlert {
  id: string;
  agent: string;
  source: string;
  source_id: string | null;
  title: string;
  message: string;
  status: 'active' | 'acknowledged' | 'resolved';
  created_at: string;
  acknowledged_at: string | null;
  resolved_at: string | null;
}

export interface AgentNotification {
  id: string;
  agent: string;
  title: string;
  message: string;
  status: 'active' | 'dismissed';
  channels_sent: string[];
  created_at: string;
  dismissed_at: string | null;
}

export interface Reminder {
  id: string;
  agent: string;
  message: string;
  context: string | null;
  due_at: string;
  status: 'pending' | 'fired' | 'cancelled';
  created_at: string;
  fired_at: string | null;
  result: string | null;
  recurrence_rule: string | null;
  series_id: string | null;
  is_recurring: boolean;
}

export interface Commitment {
  id: number;
  agent_slug: string;
  text: string;
  due_at: string | null;
  source_conversation_id: string | null;
  status: 'active' | 'done' | 'dismissed' | 'expired';
  created_at: string;
  surfaced_count: number;
  last_surfaced_at: string | null;
}

export type GmailScopeLevel = 'none' | 'read' | 'send';
export type CalendarScopeLevel = 'none' | 'read' | 'full';
export type DriveScopeLevel = 'none' | 'file' | 'readonly' | 'full';

export interface GoogleScopeGrants {
  gmail: GmailScopeLevel;
  calendar: CalendarScopeLevel;
  drive: DriveScopeLevel;
}

export interface GoogleAccount {
  id: string;
  email: string;
  scope_grants: GoogleScopeGrants;
  connection_status: string;
}

export interface Conversation {
  id: string;
  title: string;
  title_edited_by_user: boolean;
  source?: string | null;
  pinned?: number;
  mode?: 'normal' | 'import';
  created_at: string;
  updated_at: string;
  message_count?: number;
  preview?: string;
}

export interface Message {
  id: string;
  conversation_id: string;
  role: 'user' | 'assistant';
  content: string;
  created_at: string;
  seq: number;
}

export interface Provider {
  id: string;
  name: string;
  connected: boolean;
  active: boolean;
  model?: string;
}

export interface BrandingConfig {
  company_name: string;
  accent_color: string;
  has_logo: boolean;
}

export interface Integration {
  id: string;
  name: string;
  description: string;
  icon: string;
  auth_type: string;
  enabled: boolean;
  configured: boolean;
  always_on?: boolean;
  deprecated?: boolean;
  connection_status?: string;
  tool_mode?: string;
  email?: string;
  scope_grants?: GoogleScopeGrants;
  google_accounts?: GoogleAccount[];
  has_app_credentials?: boolean;
  app_id?: string;
  agent_id?: string;
  corp_id?: string;
  app_agent_id?: string;
  has_corp_secret?: boolean;
  has_callback_token?: boolean;
  has_encoding_aes_key?: boolean;
  has_app_secret?: boolean;
}

// CRM types

export interface CrmContact {
  id: number;
  name: string;
  email: string;
  phone: string;
  company: string;
  title: string;
  source: string;
  status: string;
  tags: string;
  notes: string;
  created_at: string;
  updated_at: string;
  // Detail view extras
  deals?: CrmDeal[];
  tasks?: CrmTask[];
  activity?: CrmActivity[];
}

export interface CrmDeal {
  id: number;
  contact_id: number | null;
  contact_name?: string;
  title: string;
  stage: string;
  value: number;
  notes: string;
  expected_close_date: string;
  probability: number;
  currency: string;
  created_at: string;
  updated_at: string;
  activity?: CrmActivity[];
}

export interface CrmTask {
  id: number;
  contact_id: number | null;
  deal_id: number | null;
  contact_name?: string;
  deal_title?: string;
  title: string;
  description: string;
  due_date: string;
  completed: number;
  priority: string;
  created_at: string;
  updated_at: string;
}

export interface CrmActivity {
  id: number;
  contact_id: number | null;
  deal_id: number | null;
  contact_name?: string;
  deal_title?: string;
  activity: string;
  note: string;
  created_at: string;
}

export interface CrmDashboard {
  total_contacts: number;
  contacts_by_status: Record<string, number>;
  pipeline_by_stage: { stage: string; count: number; total_value: number }[];
  total_pipeline_value: number;
  overdue_tasks: number;
  pending_tasks: number;
  recent_activity: CrmActivity[];
  top_deals: CrmDeal[];
}

// Provider status (from GET /api/providers)
export interface ProviderStatus {
  active_provider: string;
  active_model: string;
  is_railway?: boolean;
  profiles: Record<string, {
    type: string;
    configured: boolean;
    key_preview?: string;
    expired?: boolean;
    base_url?: string;
  }>;
}

// Context usage (returned from SSE 'usage' event)
// contextTokens is the cache-inclusive total the model read this turn (how full
// the context window is); contextWindow is the model's window size.
export interface ContextUsage {
  contextTokens: number;
  contextWindow: number;
}

// Tool mode for 3-tier tool permissions
export type ToolMode = 'read-only' | 'normal' | 'power';

// Training type for onboarding vs improve flows
export type TrainingType = 'topic' | 'improve' | null;

// SSE event types
export type SSEEvent =
  | { type: 'conversation_id'; id: string }
  | { type: 'text'; text: string }
  | { type: 'tool_start'; tool: string; tool_use_id: string }
  | { type: 'tool_args'; tool: string; tool_use_id: string; args: Record<string, unknown>; description?: string }
  | { type: 'tool_end'; tool: string; tool_use_id: string; result: unknown; elapsed_ms?: number; duration_ms?: number }
  | { type: 'confirm'; tool: string; args: Record<string, unknown>; tool_use_id: string; msg_id?: string; description: string }
  | { type: 'plan_ready'; plan: string }
  | { type: 'usage'; input_tokens: number; output_tokens: number; context_tokens: number; context_window: number }
  | { type: 'report'; report: { id: string; title: string; subtitle?: string; sections: unknown[]; created_at: string } }
  | { type: 'title_update'; title: string; conversation_id: string }
  | { type: 'done'; model?: string; tier?: string }
  | { type: 'error'; error: string };

