// Everything else is a cloud/remote provider. Keep them visually separated.
type ProviderDef = {
  id: string;
  name: string;
  tabs: { id: AuthTab; label: string }[];
  defaultTab: AuthTab;
  local?: boolean;
};

const providers: ProviderDef[] = [
  {
    id: 'anthropic',
    name: 'Anthropic (Claude)',
    tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
    defaultTab: 'api-key' as AuthTab,
  },
  {
    id: 'openai',
    name: 'OpenAI (GPT)',
    tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
    defaultTab: 'api-key' as AuthTab,
  },
  {
    id: 'deepseek',
    name: 'DeepSeek',
    tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
    defaultTab: 'api-key' as AuthTab,
  },
  {
    id: 'kimi',
    name: 'Kimi',
    tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
    defaultTab: 'api-key' as AuthTab,
  },
  {
    id: 'google',
    name: 'Google (Gemini)',
    tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
    defaultTab: 'api-key' as AuthTab,
  },
  {
    id: 'together',
    name: 'Together AI',
    tabs: [{ id: 'together-setup' as AuthTab, label: t('providers.apiKey') }],
    defaultTab: 'together-setup' as AuthTab,
  },
  ...(!status?.is_railway
    ? [{
        id: 'ollama',
        name: 'Ollama (Local)',
        tabs: [{ id: 'ollama-setup' as AuthTab, label: t('providers.localSetup') }],
        defaultTab: 'ollama-setup' as AuthTab,
        local: true,
      }]
    : []),
];

const cloudProviders = providers.filter(p => !p.local);
const localProviders = providers.filter(p => p.local);

function getTab(providerId: string): AuthTab {
  return authTab[providerId] || providers.find(p => p.id === providerId)!.defaultTab;
}

